// Package: Microsoft.Extensions.AI
// Install: dotnet add package Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;
using OpenAI;

var openAIClient = new OpenAIClient(apiKey: "your-api-key");

// Unified embedding client
IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator =
    openAIClient.AsEmbeddingGenerator("text-embedding-3-small");

// Unified chat client
IChatClient chatClient = openAIClient.AsChatClient("gpt-4o-mini");

// Sample usage: generate an embedding
Embedding<float> embedding = await embeddingGenerator.GenerateAsync(
    "What is the capital of France?");

Console.WriteLine($"Embedding dimensions: {embedding.Vector.Length}");
// Expected output: Embedding dimensions: 1536
